import networkx as nx,itertools,json

def residuals(G):
 n=len(G); E=[(1<<a)|(1<<b) for a,b in G.edges()]
 for s in range(1<<n):
  if all(s&e!=e for e in E):yield G.subgraph([v for v in G if not (s>>v&1)])
def typ(F):
 ds=dict(F.degree())
 if max(ds.values(),default=0)>2:return 0
 comps=[F.subgraph(c) for c in nx.connected_components(F)]
 if all(len(c)<=3 and c.number_of_edges()<len(c) for c in comps):return 1
 if all(len(c)<=4 and c.number_of_edges()<len(c) for c in comps):return 2
 if all(len(c)<=3 for c in comps):return 3
 return 0
for q in range(1,7):
 count=0
 for ns in itertools.combinations_with_replacement(range(3,16),q):
  if any(x.bit_count()<2 for x in ns):continue
  G=nx.star_graph(3)
  for i,s in enumerate(ns,4):
   G.add_node(i);G.add_edges_from((i,j) for j in range(4) if s>>j&1)
  seen=set()
  for F in residuals(G):
   t=typ(F)
   if t==1:break
   seen.add(t)
  else:
   if 2 in seen and 3 in seen:
    print('FOUND',q,ns,list(G.edges()),flush=True)
    with open('workspace/agent2_H.json','w') as f:json.dump(nx.node_link_data(G),f)
    raise SystemExit
  count+=1
 print('q',q,'done',count,flush=True)

